# ------------------------- protocolos obligatorios



def P(*items):
    out = []
    for it in items:
        if isinstance(it, list):
            out += it
            continue
        if isinstance(it, tuple):
            out.append(it)
            continue
        partes = it.split("|")
        out.append((partes[0], partes[1:] or [partes[0].lower()]))
    return out


